describe('Virus Scan Status for Uploaded Files', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display virus scan status after successful file upload', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Upload a valid file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@fileUpload');

    // Verify success message and file name display
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');
    cy.get('[data-testid="file-name-display"]').should('be.visible').should('contain', 'test-file.pdf');

    // Verify virus scan status is displayed
    cy.get('[data-testid="scan-status"]').should('be.visible').should('contain', 'Virus scan in progress');

    // Wait for scan completion
    cy.intercept('GET', '/api/files/scan-status').as('scanStatus');
    cy.get('[data-testid="refresh-scan-button"]').click();
    cy.wait('@scanStatus');

    // Verify scan completed and status is clean
    cy.get('[data-testid="scan-status"]').should('be.visible').should('contain', 'Virus scan complete');
    cy.get('[data-testid="scan-result"]').should('be.visible').should('contain', 'No viruses found');
    cy.get('[data-testid="scan-result"]').should('have.class', 'clean');
  });

  it('should handle virus detection and display appropriate warning', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Upload a file with a virus
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/infected-file.exe');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for upload and scan
    cy.wait('@fileUpload');

    // Verify scan status is displayed
    cy.get('[data-testid="scan-status"]').should('be.visible').should('contain', 'Virus scan in progress');

    // Wait for scan completion with virus detected
    cy.intercept('GET', '/api/files/scan-status').as('scanStatus');
    cy.get('[data-testid="refresh-scan-button"]').click();
    cy.wait('@scanStatus');

    // Verify virus detected warning is displayed
    cy.get('[data-testid="scan-status"]').should('be.visible').should('contain', 'Virus scan complete');
    cy.get('[data-testid="scan-result"]').should('be.visible').should('contain', 'Virus detected');
    cy.get('[data-testid="scan-result"]').should('have.class', 'infected');

    // Verify user is prompted to take action
    cy.get('[data-testid="action-button"]').should('be.visible').should('contain', 'Quarantine file');

    // Verify file is not available for download
    cy.get('[data-testid="download-button"]').should('not.exist');
  });
});
